import { crc32, deflateRawSync } from 'node:zlib';

/**
 * File writers for list exports (part 03.03, FR-06, BR-02): CSV, XLSX and PDF from the same rows, each with a "generated by / at /
 * filters" footer. No package is needed: XLSX is a small zip of XML parts (Node's zlib gives deflate and CRC-32), PDF is written as
 * text pages in a standard font. Text that a spreadsheet would run as a formula (= + - @, tab, carriage return) is made inert
 * (section 13). `columns` are [{ key, label, type }]; `rows` are presented values (already masked).
 */
export const FORMATS = { csv: 'text/csv; charset=utf-8', xlsx: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', pdf: 'application/pdf' };

/** A cell a spreadsheet will never execute: a leading = + - @ (or tab / CR) gets an apostrophe. Numbers stay numbers. */
export function inert(value) {
  if (value === null || value === undefined) return '';
  if (typeof value === 'number') return value;
  const s = String(value);
  return /^[=+\-@\t\r]/.test(s) && !/^-?\d+(\.\d+)?$/.test(s) ? `'${s}` : s;
}

export function footerLines({ title, generatedBy, generatedAt, filters, rows }) {
  return [`${title}: ${rows} row(s)`, `Generated by ${generatedBy} at ${generatedAt} (IST)`, `Filters: ${filters || 'none'}`];
}

export function toCsv({ columns, rows, footer }) {
  const cell = (v) => {
    const s = String(inert(v));
    return /[",\n\r]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
  };
  const lines = [columns.map((c) => cell(c.label)).join(','), ...rows.map((r) => columns.map((c) => cell(r[c.key])).join(','))];
  if (footer) lines.push('', ...footer.map((l) => cell(l)));
  return Buffer.from(`\uFEFF${lines.join('\r\n')}\r\n`, 'utf8');
}

// ---- XLSX ----
const xml = (s) => String(s).replace(/[<>&"']/g, (c) => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;', '"': '&quot;', "'": '&apos;' }[c])).split('').filter((ch) => { const n = ch.charCodeAt(0); return n >= 32 || n === 9 || n === 10 || n === 13; }).join(''); // XML 1.0 forbids other control characters
const colName = (i) => { let s = ''; let n = i + 1; while (n) { const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = Math.floor((n - 1) / 26); } return s; };

function zip(files) {
  const parts = [];
  const central = [];
  let offset = 0;
  for (const { name, data } of files) {
    const nameBuf = Buffer.from(name, 'utf8');
    const body = deflateRawSync(data);
    const crc = crc32(data);
    const local = Buffer.alloc(30);
    local.writeUInt32LE(0x04034b50, 0); local.writeUInt16LE(20, 4); local.writeUInt16LE(0x0800, 6); local.writeUInt16LE(8, 8);
    local.writeUInt32LE(0, 10); local.writeUInt32LE(crc, 14); local.writeUInt32LE(body.length, 18); local.writeUInt32LE(data.length, 22);
    local.writeUInt16LE(nameBuf.length, 26); local.writeUInt16LE(0, 28);
    parts.push(local, nameBuf, body);
    const c = Buffer.alloc(46);
    c.writeUInt32LE(0x02014b50, 0); c.writeUInt16LE(20, 4); c.writeUInt16LE(20, 6); c.writeUInt16LE(0x0800, 8); c.writeUInt16LE(8, 10);
    c.writeUInt32LE(0, 12); c.writeUInt32LE(crc, 16); c.writeUInt32LE(body.length, 20); c.writeUInt32LE(data.length, 24);
    c.writeUInt16LE(nameBuf.length, 28); c.writeUInt32LE(offset, 42);
    central.push(c, nameBuf);
    offset += local.length + nameBuf.length + body.length;
  }
  const centralBuf = Buffer.concat(central);
  const end = Buffer.alloc(22);
  end.writeUInt32LE(0x06054b50, 0); end.writeUInt16LE(files.length, 8); end.writeUInt16LE(files.length, 10);
  end.writeUInt32LE(centralBuf.length, 12); end.writeUInt32LE(offset, 16);
  return Buffer.concat([...parts, centralBuf, end]);
}

/** One worksheet: a bold header row, numbers as numbers (money with two decimals, Indian grouping), dates as text DD-MMM-YYYY, the footer below. */
export function toXlsx({ columns, rows, footer, sheetName = 'Export' }) {
  const numeric = (c) => ['number', 'money', 'id'].includes(c.type);
  const cell = (ref, v, c, style = 0) => {
    if (v === null || v === undefined || v === '') return `<c r="${ref}"${style ? ` s="${style}"` : ''}/>`;
    if (c && numeric(c) && typeof v !== 'string' ? true : c && numeric(c) && /^-?\d+(\.\d+)?$/.test(String(v))) return `<c r="${ref}" s="${c.type === 'money' ? 2 : 0}"><v>${Number(v)}</v></c>`;
    return `<c r="${ref}" t="inlineStr"${style ? ` s="${style}"` : ''}><is><t xml:space="preserve">${xml(inert(v))}</t></is></c>`;
  };
  const out = [];
  out.push(`<row r="1">${columns.map((c, i) => cell(`${colName(i)}1`, c.label, null, 1)).join('')}</row>`);
  rows.forEach((r, j) => out.push(`<row r="${j + 2}">${columns.map((c, i) => cell(`${colName(i)}${j + 2}`, r[c.key], c)).join('')}</row>`));
  let n = rows.length + 2;
  for (const line of footer ?? []) { n += 1; out.push(`<row r="${n}">${cell(`A${n}`, line, null, 3)}</row>`); }
  const widths = columns.map((c) => Math.min(60, Math.max(10, String(c.label).length + 2, ...rows.slice(0, 200).map((r) => String(r[c.key] ?? '').length + 2))));
  const sheet = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><cols>${widths.map((w, i) => `<col min="${i + 1}" max="${i + 1}" width="${w}" customWidth="1"/>`).join('')}</cols><sheetData>${out.join('')}</sheetData></worksheet>`;
  const files = [
    { name: '[Content_Types].xml', data: '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/></Types>' },
    { name: '_rels/.rels', data: '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>' },
    { name: 'xl/workbook.xml', data: `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="${xml(sheetName.slice(0, 31))}" sheetId="1" r:id="rId1"/></sheets></workbook>` },
    { name: 'xl/_rels/workbook.xml.rels', data: '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>' },
    { name: 'xl/styles.xml', data: '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><numFmts count="1"><numFmt numFmtId="164" formatCode="[&gt;=10000000]##\\,##\\,##\\,##0.00;[&gt;=100000]##\\,##\\,##0.00;##,##0.00"/></numFmts><fonts count="3"><font><sz val="11"/><name val="Calibri"/></font><font><b/><sz val="11"/><name val="Calibri"/></font><font><i/><sz val="9"/><name val="Calibri"/></font></fonts><fills count="2"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf/></cellStyleXfs><cellXfs count="4"><xf/><xf fontId="1" applyFont="1"/><xf numFmtId="164" applyNumberFormat="1"/><xf fontId="2" applyFont="1"/></cellXfs></styleSheet>' },
    { name: 'xl/worksheets/sheet1.xml', data: sheet },
  ];
  return zip(files.map((f) => ({ name: f.name, data: Buffer.from(f.data, 'utf8') })));
}

// ---- PDF ----
/** Text that the standard PDF fonts can show (Latin-1); the rupee sign becomes "Rs." and other characters "?". */
const pdfText = (s) => String(s ?? '').replace(/₹/g, 'Rs.').replace(/[^\x20-\x7E\xA0-\xFF]/g, '?').replace(/[\\()]/g, (c) => `\\${c}`);

/** A landscape A4 table in Helvetica: header row on every page, page numbers, the footer on the last page. */
export function toPdf({ columns, rows, footer, title = 'Export' }) {
  const W = 842; const H = 595; const M = 36; const LINE = 13; const SIZE = 8;
  const usable = W - 2 * M;
  const raw = columns.map((c) => Math.max(String(c.label).length, ...rows.slice(0, 300).map((r) => String(r[c.key] ?? '').length)));
  const sum = raw.reduce((a, b) => a + b, 0) || 1;
  const widths = raw.map((w) => Math.max(40, (w / sum) * usable));
  const scale = usable / widths.reduce((a, b) => a + b, 0);
  const cols = widths.map((w) => w * scale);
  const fit = (s, w) => { const max = Math.max(3, Math.floor(w / (SIZE * 0.5))); const t = String(s ?? ''); return t.length > max ? `${t.slice(0, max - 1)}~` : t; };
  const perPage = Math.floor((H - 2 * M - 3 * LINE) / LINE);
  const pages = [];
  for (let i = 0; i < Math.max(1, rows.length); i += perPage) pages.push(rows.slice(i, i + perPage));
  const streams = pages.map((chunk, p) => {
    const ops = [];
    const text = (x, y, s, bold = false, size = SIZE) => ops.push(`BT /${bold ? 'F2' : 'F1'} ${size} Tf ${x.toFixed(1)} ${y.toFixed(1)} Td (${pdfText(s)}) Tj ET`);
    let y = H - M;
    text(M, y, title, true, 11);
    text(W - M - 80, y, `Page ${p + 1} of ${pages.length}`);
    y -= LINE * 1.6;
    let x = M;
    columns.forEach((c, i) => { text(x, y, fit(c.label, cols[i]), true); x += cols[i]; });
    ops.push(`${M} ${y - 3} m ${W - M} ${y - 3} l S`);
    for (const r of chunk) {
      y -= LINE;
      x = M;
      columns.forEach((c, i) => {
        const v = fit(r[c.key], cols[i]);
        const right = ['number', 'money'].includes(c.type);
        text(right ? x + cols[i] - v.length * SIZE * 0.5 - 4 : x, y, v);
        x += cols[i];
      });
    }
    if (p === pages.length - 1) for (const l of footer ?? []) { y -= LINE; text(M, y, l, false, 7); }
    return ops.join('\n');
  });
  const objects = ['<< /Type /Catalog /Pages 2 0 R >>', null, '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>', '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>'];
  const kids = [];
  for (const s of streams) {
    const content = Buffer.from(s, 'latin1');
    objects.push(`<< /Length ${content.length} >>\nstream\n${s}\nendstream`);
    const contentId = objects.length;
    objects.push(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${W} ${H}] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> >> /Contents ${contentId} 0 R >>`);
    kids.push(`${objects.length} 0 R`);
  }
  objects[1] = `<< /Type /Pages /Kids [${kids.join(' ')}] /Count ${kids.length} >>`;
  let body = '%PDF-1.4\n%\xE2\xE3\xCF\xD3\n';
  const offsets = [];
  objects.forEach((o, i) => { offsets.push(Buffer.byteLength(body, 'latin1')); body += `${i + 1} 0 obj\n${o}\nendobj\n`; });
  const xref = Buffer.byteLength(body, 'latin1');
  body += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n${offsets.map((o) => `${String(o).padStart(10, '0')} 00000 n \n`).join('')}trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`;
  return Buffer.from(body, 'latin1');
}

/** Write rows in a format. */
export function writeExport(format, opts) {
  if (format === 'csv') return toCsv(opts);
  if (format === 'xlsx') return toXlsx(opts);
  if (format === 'pdf') return toPdf(opts);
  throw new Error(`Unknown export format ${format}`);
}
